/*\n  # Fix email_sends Foreign Key Constraint\n\n  1. Changes\n    - Drop the existing foreign key constraint on email_sends.contact_id that references leads(id)\n    - Add new foreign key constraint on email_sends.contact_id that references newsletter_leads(id)\n    \n  2. Reason\n    - The application uses newsletter_leads table for email campaigns, not the leads table\n    - This was causing foreign key violations when trying to create email send records\n    \n  3. Important Notes\n    - This migration safely handles the constraint change\n    - Existing data in email_sends will remain intact\n    - Future inserts will now correctly reference newsletter_leads table\n*/\n\n-- Drop the old foreign key constraint if it exists\nDO $$\nBEGIN\n  IF EXISTS (\n    SELECT 1 FROM information_schema.table_constraints \n    WHERE constraint_name = 'email_sends_contact_id_fkey' \n    AND table_name = 'email_sends'\n  ) THEN\n    ALTER TABLE email_sends DROP CONSTRAINT email_sends_contact_id_fkey;
\n  END IF;
\nEND $$;
\n\n-- Add new foreign key constraint pointing to newsletter_leads\nALTER TABLE email_sends \n  ADD CONSTRAINT email_sends_contact_id_fkey \n  FOREIGN KEY (contact_id) \n  REFERENCES newsletter_leads(id) \n  ON DELETE CASCADE;
;
